const items = $input.all();

// Extraímos o array de transações do payload bruto
const rawTransactions = items[0].json.data;

const normalizedData = rawTransactions.map(raw => {
    return {
        transaction_id: raw.id || raw.txid || raw.transactionIdentifier || raw.transactionId, // Normaliza IDs
        amount: parseFloat(raw.amount || raw.value).toFixed(2), // Garante o float com 2 casas
        currency: raw.currency || 'BRL',
        timestamp: new Date(raw.bookingDate || raw.date).toISOString(), // Padroniza para ISO 8601
        source_bank: raw.institution_name,
        category_raw: raw.description || raw.narrative // Unifica a descrição bruta
    };
});

// O N8N exige que o retorno seja um array de objetos encapsulados na chave 'json'
return normalizedData.map(item => ({ json: item }));

