// 1. Busca os dados limpos diretamente do nó da Camada Silver
const silverData = $('Camada Silver (Clean Data)').all();
const transactions = silverData.map(item => item.json);

// 2. Captura a resposta do nó Vertex AI (Agente)
// Em nós de IA do N8N, a resposta costuma vir em 'output', 'text' ou 'response'
const aiRawOutput = $input.first().json.output || $input.first().json.text || $input.first().json.response || "";

// 3. Parser Robusto (Prevenção de Erros de LLM)
// Remove formatações Markdown indesejadas que o LLM possa ter incluído
const cleanJsonString = aiRawOutput.replace(/```json/gi, '').replace(/```/g, '').trim();

let ai_insights = [];
try {
    // Tenta converter a string gerada pela IA em um array de objetos reais
    ai_insights = JSON.parse(cleanJsonString);
} catch (error) {
    throw new Error("Falha Crítica: O Vertex AI não retornou um JSON válido. Retorno da IA: " + aiRawOutput);
}

// 4. Variáveis da Fórmula
let fluxoCaixa = 0;
let qtdInvestimentos = 0; 
let esgTotal = 0;

// 5. Merge entre o dado da API (Silver) e o Insight da IA (Gold)
const enrichedData = transactions.map(tx => {
    const insight = ai_insights.find(i => i.id === tx.transaction_id);
    const category = insight ? insight.category : "Indefinido";
    const esg = insight ? insight.esg_score : 5;

    fluxoCaixa += parseFloat(tx.amount);
    esgTotal += esg;

    if (category === "Investment") {
        qtdInvestimentos += 1; // Contabiliza a frequência de aportes
    }

    return {
        ...tx,
        category_enriched: category,
        esg_score: esg
    };
});

// 6. NORMALIZAÇÃO DAS GRANDEZAS (Teto 1000 para cada pilar)
// Assume que R$ 5.000,00 de fluxo mensal é o teto para nota máxima neste pilar
const scoreFluxo = Math.min((fluxoCaixa / 5000) * 1000, 1000); 

// Assume que 5 aportes de investimento garantem nota máxima neste pilar (200 pts por aporte)
const scoreInvestimento = Math.min(qtdInvestimentos * 200, 1000); 

// Fidelidade convertida para a escala de 1000 (ex: 850 = 85% de histórico positivo)
const scoreFidelidade = 850; 

// 7. Pesos e Cálculo da Fórmula
const W1 = 0.4;
const W2 = 0.3;
const W3 = 0.3;

let scoreFinal = (W1 * scoreFluxo) + (W2 * scoreInvestimento) + (W3 * scoreFidelidade);

// 8. ESG Link (Bônus Verde)
const mediaEsg = transactions.length > 0 ? (esgTotal / transactions.length) : 5;
if (mediaEsg >= 7) {
    scoreFinal *= 1.1; // Bônus Verde de 10%
}

// Garante que o score final jamais ultrapasse o limite regulatório de 1000
const scoreDefinitivo = Math.min(Math.round(scoreFinal), 1000);

return [
  {
    json: {
      customer_id: "USER-12345",
      alternative_credit_score: scoreDefinitivo,
      average_esg_score: parseFloat(mediaEsg.toFixed(1)),
      transactions_enriched: enrichedData
    }
  }
];

