const categories = ["Investment", "Essential", "Leisure", "Other"];

function generateTransactions(userIndex) {
  const txCount = Math.floor(Math.random() * 5) + 8; // 8 a 12 transações
  const transactions = [];

  for (let i = 0; i < txCount; i++) {
    const category =
      categories[Math.floor(Math.random() * categories.length)];

let esg = 5.0;
    if (category === "Investment") esg = (Math.random() * (10 - 8) + 8).toFixed(1); // 8 a 10
    else if (category === "Essential") esg = (Math.random() * (7 - 5) + 5).toFixed(1); // 5 a 7
    else if (category === "Leisure") esg = (Math.random() * (5 - 2) + 2).toFixed(1); // 2 a 5
    else esg = (Math.random() * (6 - 4) + 4).toFixed(1); // 4 a 6

    transactions.push({
      id: `tx_${userIndex}_${i + 1}`,
      category_enriched: category,
      esg_score: parseFloat(esg) // <--- O CAMPO QUE ESTAVA FALTANDO!
    });
  }

  return transactions;
}

